// Tidewall UI fonts (LAS-25), inlined so game.html stays one file. Cinzel (display: titles, menu, card names; variable
// weight, latin subset from Google Fonts) and Barlow 400/600 (body and numbers; the same files Tropebrawl embeds).
// Both SIL Open Font License 1.1: free to embed and sell with the game; credit them in the game credits. ui.js uses them.
(function () {
'use strict';
if (typeof document === 'undefined') return;
const st = document.createElement('style'); st.id = 'tw-fonts';
st.textContent = "@font-face{font-family:'Cinzel';font-style:normal;font-weight:400 900;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Barlow';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Barlow';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}";
document.head.appendChild(st);
})();
